import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'exercise_figure_3d_baseline.dart';

void main() {
  test('incorrect ankle-radius expectation also rejects the unchanged baseline toe', () {
    final catalog = Figure3DCatalog.fromJsonString(File('build/qa/035/baseline-8ef2df4.json').readAsStringSync());
    final reference = catalog.forExercise('Plancha lateral')!;
    final support = liftSkeleton(reference.skeletonAt(0), reference).p;
    expect(support['nearToe']!.y, closeTo(-.9, .05));
  });
}
